**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
using namespace std;

int main() {
    ifstream plik("macierz.txt");
    int m[5][5];
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            plik >> m[i][j];
    int sumB = 0, sumI = 0;
    int maxB = m[0][0], minI = m[1][1];
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            if (i == 0 || i == 4 || j == 0 || j == 4) {
                sumB += m[i][j];
                if (m[i][j] > maxB) maxB = m[i][j];
            } else {
                sumI += m[i][j];
                if (m[i][j] < minI) minI = m[i][j];
            }
        }
    }
    cout << "Suma brzegowych: " << sumB << endl;
    cout << "Suma wewnetrznych: " << sumI << endl;
    cout << "Max brzegowy: " << maxB << endl;
    cout << "Min wewnetrzny: " << minI << endl;
    return 0;
}
```

Weryfikacja:
- Brzegowe: 3+7+1+4+5+6+9+4+2+8+1+2+9+3+5+7 = 76
- Wewnetrzne (3x3): 2+8+3+5+1+7+3+6+4 = 39
- Max brzegowy: 9, Min wewnetrzny: 1
